import React, { useState, useEffect } from "react";
import "./styles/schedule-page.css";
import Sidebar from './components/sidebar';
import FullCalendar from '@fullcalendar/react';
import dayGridPlugin from '@fullcalendar/daygrid';
import timeGridPlugin from '@fullcalendar/timegrid';
import AddEventModal from './components/AddEventModal'; 

const SchedulePage = ({ userRole }) => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Determine if the current user is an admin
  const isAdmin = userRole === 'admin';

  // Fetch schedules from the backend
  const fetchSchedules = async () => {
    try {
      setLoading(true);
      const response = await fetch('http://localhost:8000/api/schedule/');
      if (!response.ok) {
        throw new Error(`HTTP error ${response.status}`);
      }
      const data = await response.json();
      if (!data.schedules || !Array.isArray(data.schedules)) {
        setError("Invalid data format received from server");
        return;
      }
      const formattedEvents = data.schedules.map(schedule => ({
        title: schedule.subject,
        start: `${schedule.date}T${schedule.start_time}`,
        end: `${schedule.date}T${schedule.end_time}`,
        extendedProps: {
          location: 'TBD',
          tutor: schedule.tutor_id,
          subject: schedule.subject
        }
      }));
      setEvents(formattedEvents);
    } catch (error) {
      console.error('Error fetching schedules:', error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSchedules();
  }, []);

  // Admin-only function to add events
  const addEventToSchedule = async (eventData) => {
    try {
      const response = await fetch('http://localhost:8000/api/schedule/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(eventData),
        credentials: 'include',
      });
      if (!response.ok) {
        throw new Error(`HTTP error ${response.status}`);
      }
      // Refresh the schedules after adding an event
      fetchSchedules();
    } catch (error) {
      console.error('Error adding event:', error);
    }
  };

  // Open the modal
  const handleAddEvent = () => {
    setIsModalOpen(true);
  };

  const renderEventContent = (eventInfo) => {
    const isMonthView = eventInfo.view.type === 'dayGridMonth';
    const start = eventInfo.event.start;
    const end = eventInfo.event.end;
    const durationMinutes = end 
      ? Math.round((end.getTime() - start.getTime()) / (1000 * 60)) 
      : 0;

    // For month view
    if (isMonthView) {
      return (
        <div className="event-content-month">
          <div className="event-title">{eventInfo.event.title}</div>
        </div>
      );
    }

    // For short events (<= 75 minutes)
    if (durationMinutes <= 75) {
      return (
        <div className="event-content event-content-short">
          <div className="event-title">{eventInfo.event.title}</div>
        </div>
      );
    }

    // For normal events
    const startTime = start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const endTime = end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    return (
      <div className="event-content">
        <div className="event-title">{eventInfo.event.title}</div>
        <div className="event-tutor-name">{eventInfo.event.extendedProps.tutor}</div>
        <div className="event-location">{eventInfo.event.extendedProps.location}</div>
        <div className="event-time">{startTime} - {endTime}</div>
      </div>
    );
  };

  return (
    <div className="schedule-page-container">
      <Sidebar />
      <div className="calendar-wrapper">
        <AddEventModal 
          isOpen={isModalOpen} 
          onClose={() => setIsModalOpen(false)} 
          onAddEvent={addEventToSchedule} 
        />

        {/* 
          Remove or comment out your old standalone button. 
          The custom FullCalendar button below replaces it.
        */}
        {/* {isAdmin && (
          <button className="add-event-button" onClick={handleAddEvent}>
            Add Event
          </button>
        )} */}

        {loading && <div>Loading schedules...</div>}
        {error && <div className="error-message">Error: {error}</div>}

        <FullCalendar
          plugins={[dayGridPlugin, timeGridPlugin]}
          initialView='timeGridWeek'
          slotMinTime={"07:00:00"}
          slotMaxTime={"20:00:00"}
          allDaySlot={false}
          expandRows={true}
          height='100%'

          // 1) Conditionally show custom "Add Event" button if user is admin
          headerToolbar={{
            left: isAdmin 
              ? 'today prev next addEventButton' 
              : 'today prev next',
            center: 'title',
            right: 'dayGridMonth,timeGridWeek'
          }}

          // 2) Define the custom button if user is admin
          customButtons={ isAdmin ? {
            addEventButton: {
              text: 'Add Event',
              click: handleAddEvent,  // same function that opens the modal
            },
          } : {} }

          buttonText={{
            today: 'Today',
            month: 'Month',
            week: 'Week'
          }}
          eventColor="#afdcd5"
          eventTextColor="#000000"
          eventContent={renderEventContent}
          eventDisplay="block"
          events={events}
          eventClick={(info) => {
            console.log("Clicked event:", info.event);
            info.el.style.borderColor = '#afdcd5';
          }}
        />
      </div>
    </div>
  );
};

export default SchedulePage;
